DELETE FROM follow
WHERE follower_no = #{followerNo}
  AND following_no = #{followingNo}

mapper.select:
SELECT COUNT(*)
FROM follow
WHERE following_no = #{userNo}

SELECT COUNT(*)
FROM follow
WHERE follower_no = #{userNo}

SELECT
    #{targetUserNo} AS targetUserNo,
    EXISTS(
        SELECT 1 FROM follow
        WHERE follower_no = #{myUserNo} AND following_no = #{targetUserNo}
    ) AS isFollowing,
    EXISTS(
        SELECT 1 FROM follow
        WHERE follower_no = #{targetUserNo} AND following_no = #{myUserNo}
    ) AS isFollower,
    (
        SELECT follow_id FROM follow
        WHERE follower_no = #{myUserNo} AND following_no = #{targetUserNo}
    ) AS followId

SELECT following_no
FROM follow
WHERE follower_no = #{userNo}
